// stripeService.js - MODO PRUEBA
const MODO_PRUEBA = true;

// Mock del servicio de Stripe para modo prueba
const mockStripeService = {
  createConnectAccount: async (email, nombre, pais) => {
    console.log('🧪 Modo prueba: Creando cuenta Stripe mock para', email);
    return { 
      accountId: 'acct_mock_' + Date.now(),
      onboardingLink: 'https://example.com/mock-onboarding'
    };
  },
  
  getOnboardingStatus: async () => {
    console.log('🧪 Modo prueba: Verificando onboarding');
    return {
      hasStripeAccount: true,
      onboardingCompleted: true,
      payoutsEnabled: true,
      chargesEnabled: true,
      detailsSubmitted: true
    };
  },
  
  createPaymentIntent: async (amount, currency, metadata) => {
    console.log('🧪 Modo prueba: Creando PaymentIntent mock por', amount, currency);
    return {
      clientSecret: 'mock_client_secret_' + Date.now(),
      paymentIntentId: 'pi_mock_' + Date.now()
    };
  },
  
  confirmPayment: async (paymentIntentId) => {
    console.log('🧪 Modo prueba: Confirmando pago mock');
    return { success: true };
  },
  
  getPublishableKey: () => {
    return 'pk_test_mock_key_for_development';
  }
};

// Si estamos en modo prueba, exportar el mock
if (MODO_PRUEBA) {
  module.exports = mockStripeService;
} else {
  // Configuración real de Stripe (solo si NO estamos en modo prueba)
  const STRIPE_PUBLISHABLE_KEY = process.env.REACT_APP_STRIPE_PUBLIC_KEY;
  
  if (!STRIPE_PUBLISHABLE_KEY) {
    console.error('❌ Stripe publishable key is missing!');
  }
  
  // Importar Stripe solo en modo real
  const { loadStripe } = require('@stripe/stripe-js');
  
  let stripePromise = null;
  const getStripe = () => {
    if (!stripePromise && STRIPE_PUBLISHABLE_KEY) {
      stripePromise = loadStripe(STRIPE_PUBLISHABLE_KEY);
    }
    return stripePromise;
  };
  
  const stripeService = {
    getStripe,
    getPublishableKey: () => STRIPE_PUBLISHABLE_KEY,
    
    createConnectAccount: async (email, nombre, pais) => {
      const response = await fetch('/api/create-connect-account', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, nombre, pais })
      });
      return response.json();
    },
    
    getOnboardingStatus: async () => {
      const response = await fetch('/api/onboarding-status');
      return response.json();
    },
    
    createPaymentIntent: async (amount, currency = 'mxn') => {
      const response = await fetch('/api/create-payment-intent', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ amount, currency })
      });
      return response.json();
    }
  };
  
  module.exports = stripeService;
}
